export type ParsedWithdrawInstruction<
  TProgram extends string = typeof AGENT_RAILS_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    owner: TAccountMetas[0];
    /** Read-only: the treasury signs the transfer as a PDA but is not mutated. */
    treasury: TAccountMetas[1];
    /** initialized mint; the handler unpacks it before the token CPI. */
    mint: TAccountMetas[2];
    /** Required for SPL / Token-2022, omitted for native SOL. */
    vaultAta?: TAccountMetas[3] | undefined;
    /** Required for native SOL, omitted otherwise. */
    solVault?: TAccountMetas[4] | undefined;
    /**
     * Token account for SPL, system account for SOL. Validated in the handler because
     * the two paths disagree on owner and layout.
     *
     */
    destination: TAccountMetas[5];
    /** Required for SPL / Token-2022, omitted for native SOL. */
    tokenProgram?: TAccountMetas[6] | undefined;
    systemProgram: TAccountMetas[7];
    eventAuthority: TAccountMetas[8];
    program: TAccountMetas[9];
  };
  data: WithdrawInstructionData;
};

export function parseWithdrawInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedWithdrawInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 10,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === AGENT_RAILS_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      owner: getNextAccount(),
      treasury: getNextAccount(),
      mint: getNextAccount(),
      vaultAta: getNextOptionalAccount(),
      solVault: getNextOptionalAccount(),
      destination: getNextAccount(),
      tokenProgram: getNextOptionalAccount(),
      systemProgram: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getWithdrawInstructionDataDecoder().decode(instruction.data),
  };
}
